{"content": "from typing import Dict, Optional

from pydantic import BaseModel, Field, ValidationInfo, field_validator


class FeatureFlags(BaseModel):
    env: str = "dev"
    rollout: Dict[str, int] = Field(default_factory=dict)
    owner: Optional[str] = Field(default=None, validate_default=True)

    @field_validator("rollout")
    @classmethod
    def percent(cls, v: Dict[str, int]) -> Dict[str, int]:
        for value in v.values():
            if not 0 <= value <= 100:
                raise ValueError("rollout must be 0-100")
        return v

    @field_validator("owner")
    @classmethod
    def default_owner(cls, v: Optional[str], info: ValidationInfo) -> str:
        return v or f"team-{info.data.get('env', 'dev')}"
"}
